package ltnc.auction.server.net;
import java.io.*; import java.math.BigDecimal; import java.net.Socket; import java.util.*;
import ltnc.auction.common.exception.*; import ltnc.auction.common.model.*; import ltnc.auction.common.protocol.*; import ltnc.auction.server.service.AuctionManager;
public final class ClientHandler implements Runnable { private final Socket socket; private final AuctionManager manager; public ClientHandler(Socket socket,AuctionManager manager){this.socket=socket;this.manager=manager;}
 @Override public void run(){try(Socket s=socket; ObjectOutputStream out=new ObjectOutputStream(s.getOutputStream()); ObjectInputStream in=new ObjectInputStream(s.getInputStream())){out.flush();Object obj;while((obj=in.readObject())!=null){if(!(obj instanceof Request req)){out.writeObject(new Response(false,"Yêu cầu không hợp lệ",null));out.flush();continue;}out.writeObject(handle(req));out.flush();}}catch(EOFException ignored){}catch(Exception e){System.err.println("Client lỗi: "+e.getMessage());}}
 private Response handle(Request r){try{return switch(r.getType()){case PING->new Response(true,"PONG",null);case LIST_AUCTIONS->new Response(true,"OK",manager.listAuctions());case PLACE_BID->{Bid b=manager.placeBid(r.getAuctionId(),r.getUsername(),r.getAmount());yield new Response(true,"Đặt giá thành công: "+b.getAmount(),null);}case LOGIN->new Response(false,"TODO: hoàn thiện xác thực tài khoản",null);case CREATE_AUCTION->new Response(false,"TODO: triển khai API tạo phiên",null);};}catch(InvalidBidException|AuctionClosedException e){return new Response(false,e.getMessage(),null);}catch(Exception e){return new Response(false,"Lỗi hệ thống: "+e.getMessage(),null);}}
}
